// Original single-purchase, full-disposition example with no later cost adjustments.
export const fxCostDefinitions={fxCapitalRecord:{title:'Keep acquisition-date cost and disposition-date proceeds in their own CAD conversions',fields:[
 ['fxOriginalUsd','Single-purchase acquisition cost, including eligible same-date costs (USD)',10000,0,500000,1000],
 ['fxSaleUsd','Full-disposition gross proceeds (USD)',12000,0,500000,1000],
 ['fxBuyCad','Acquisition-date rate: CAD for USD 1',1.25,.5,2,.01],
 ['fxSaleCad','Disposition-date rate: CAD for USD 1',1.35,.5,2,.01],
 ['fxSellingCad','Eligible disposition expenses already in CAD',50,0,5000,10]
 ]}};
export function fxCostLedger(i,overrides={}){
 const p={...i,...overrides},costCad=p.fxOriginalUsd*p.fxBuyCad,proceedsCad=p.fxSaleUsd*p.fxSaleCad,usdChange=p.fxSaleUsd-p.fxOriginalUsd;
 return {costCad,proceedsCad,usdChange,gainCad:proceedsCad-costCad-p.fxSellingCad,usdChangeCad:usdChange*p.fxSaleCad,costFxEffect:p.fxOriginalUsd*(p.fxSaleCad-p.fxBuyCad)};
}
export function fxCostResult(kind,input){
 if(kind!=='fxCapitalRecord')throw Error('Unknown dated foreign-cost record');
 const rateCase=v=>Number(v.toFixed(4)),usdCase=v=>Number(v.toFixed(2));
 const r=fxCostLedger(input),rates=[...new Set([input.fxBuyCad*.8,input.fxBuyCad,input.fxSaleCad,input.fxBuyCad*1.2].map(rateCase))].sort((a,b)=>a-b),matrixRates=[...new Set([input.fxBuyCad*.8,input.fxSaleCad,input.fxBuyCad*1.2].map(rateCase))].sort((a,b)=>a-b),proceeds=[...new Set([input.fxSaleUsd*.75,input.fxSaleUsd,input.fxSaleUsd*1.25].map(usdCase))];
 return {metrics:[['CAD arithmetic gain or loss before inclusion',r.gainCad,'money'],['Historical CAD acquisition cost',r.costCad,'money'],['CAD translation of gross disposition proceeds',r.proceedsCad,'money']],
 note:'Original hypothetical USD capital-property example for one purchase, no later adjusted-cost changes and a full disposition. Acquisition cost is translated at its independently entered acquisition-date CAD-per-USD rate; gross disposition proceeds use the disposition-date rate. Eligible disposition expenses are supplied already in CAD and subtracted once. No quoted market rates are imported. All chart results are CAD arithmetic before an inclusion rate, tax, loss-eligibility rules or other income. No actual currency conversion, settlement receipt, spending cash, later disposition of USD cash, pooled-cost calculation, partial sale, reinvestment, dividend or registered-account treatment is modeled. A negative result is an arithmetic loss, not a determination that it may be claimed.',
 charts:[
 {id:'fx-cost-dated-cad-record',type:'waterfall',unit:'money',unitLabel:'CAD arithmetic before inclusion or personal tax',title:'Translate each dated amount before reconciling the result',rows:[{label:'USD proceeds at sale-date rate',value:r.proceedsCad},{label:'Cost at acquisition-date rate',value:-r.costCad},{label:'Disposition expenses in CAD',value:-input.fxSellingCad}],totalLabel:'CAD arithmetic gain or loss',note:'The CAD cost is the assumed single-purchase adjusted cost base with no later adjustments. Proceeds and cost use their own independently entered rates. The CAD expense is not translated a second time. Translating USD proceeds for a record does not mean a bank actually converted the sale cash into CAD.'},
 {id:'fx-cost-price-currency-bridge',type:'waterfall',unit:'money',unitLabel:'CAD contributions to the same arithmetic gain/loss',title:'Reconcile the USD change and the currency effect without double counting',rows:[{label:'USD change at sale-date rate',value:r.usdChangeCad},{label:'FX change on original USD cost',value:r.costFxEffect},{label:'Disposition expenses in CAD',value:-input.fxSellingCad}],totalLabel:'Same CAD arithmetic result',note:'One exact decomposition: (USD proceeds − original USD cost) × sale rate, plus original USD cost × (sale rate − acquisition rate), less the CAD expense. The first term already uses the full sale rate, so no extra price/currency interaction is added. These are accounting contributions, not separately received cash or a measured hedging payoff.'},
 {id:'fx-cost-equal-usd-cases',type:'signedbar',unit:'money',unitLabel:'CAD arithmetic gain/loss when USD proceeds equal original USD cost',title:'Equal USD proceeds and cost can still leave a CAD gain or loss',rows:rates.map(rate=>({label:'Sale rate '+rate.toFixed(4)+' CAD/USD',value:fxCostLedger(input,{fxSaleUsd:input.fxOriginalUsd,fxSaleCad:rate}).gainCad})),note:'Every row replaces USD gross proceeds with the original USD acquisition cost, making the USD difference zero. The entered acquisition rate, original cost and CAD selling expense stay fixed. The rows use 80%, 100% and 120% of the acquisition rate plus the selected sale rate, with stress rates rounded to four decimals before calculation and duplicate rates removed. Currency translation and the expense can still create a CAD difference; no gain probability, tax payable or deductible-loss ruling is supplied.'},
 {id:'fx-cost-sale-sensitivity',type:'heatmap',unit:'money',signed:true,unitLabel:'CAD arithmetic gain/loss · rows: sale CAD/USD rate; columns: gross USD proceeds',rowLabel:'Sale-date rate (CAD/USD)',title:'Stress the sale proceeds and the sale-date rate together',columns:proceeds.map(x=>x.toLocaleString('en-CA',{maximumFractionDigits:2})),rows:matrixRates.map(rate=>({label:rate.toFixed(4),values:proceeds.map(amount=>fxCostLedger(input,{fxSaleUsd:amount,fxSaleCad:rate}).gainCad)})),note:'The original USD acquisition cost, acquisition-date rate and CAD expense stay fixed. Column amounts are USD proceeds; cell values are CAD results before inclusion and tax. Rate rows use 80% and 120% of the acquisition rate plus the selected sale rate. USD proceeds columns use 75%, 100% and 125% of selected proceeds; stress rates are rounded to four decimals and USD proceeds to cents before calculation, with duplicate cases removed. These are authored stresses rather than market quotes or a confidence range. A negative cell remains an arithmetic loss whose eligibility requires separate review.'}
 ]};
}
